lines = open("region.fasta").read().splitlines()
seq = "".join(lines[1:]).upper()
# find simple repeats / tandem repeats
def find_tandem(seq, min_unit=2, min_copies=3):
    res=[]
    n=len(seq)
    for u in range(min_unit, 21):
        for i in range(0, n-u*min_copies+1):
            unit = seq[i:i+u]
            cnt=1
            j=i+u
            while seq[j:j+u]==unit:
                cnt+=1; j+=u
            if cnt>=min_copies:
                res.append((i, i+cnt*u, unit, cnt))
    return res

