def orfs(s, minaa=80):
    out=[]
    for strand,ss in (("+",s),("-",rc(s))):
        for f in range(3):
            i=f
            while i+3<=len(ss):
                if ss[i:i+3]=='ATG':
                    j=i
                    while j+3<=len(ss):
                        cod=ss[j:j+3]
                        if cod in ('TAA','TAG','TGA'):
                            aa=(j-i)//3
                            if aa>=minaa:
                                if strand=="+":
                                    out.append((strand,f,i,j+3,aa))
                                else:
                                    L=len(s)
                                    out.append((strand,f,L-(j+3),L-i,aa))
                            break
                        j+=3
                    i+=3
                else:
                    i+=3
    return out

