n=len(seq)
import re
def gc(s): return (s.count('G')+s.count('C'))/len(s)
def oe(s):
    c=s.count('C'); g=s.count('G'); cg=len(re.findall("CG",s))
    if c==0 or g==0: return 0
    return cg/(c*g/len(s))
